// Stdin returns a singleton ContextReader wrapped around os.Stdin.
//
// os.Stdin should not be used directly after the first call to this function
// to avoid losing data.
func Stdin() StdinReader {
	stdinMU.Lock()
	defer stdinMU.Unlock()
	if stdin == nil {
